use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs = input["jobs"].as_array().unwrap();
    let quantum = input["quantum"].as_i64().unwrap();
    let mut work_done = vec![0; jobs.len()];
    let mut result = Vec::new();
    let mut total_work: i64 = jobs.iter().map(|j| j.as_i64().unwrap()).sum();

    while total_work > 0 {
        for i in 0..jobs.len() {
            if work_done[i] < jobs[i].as_i64().unwrap() {
                let work_to_do = jobs[i].as_i64().unwrap() - work_done[i];
                let work_this_turn = work_to_do.min(quantum);
                work_done[i] += work_this_turn;
                total_work -= work_this_turn;

                if work_done[i] == jobs[i].as_i64().unwrap() {
                    result.push(i);
                }
            }
        }
    }

    Value::Array(result.into_iter().map(|i| Value::Number(i.into())).collect())
}
